namespace {bool tracking=false;uint64_t allocations=0;void check(bool b,const char*s){if(!b)throw std::logic_error(s);}}
void*operator new(std::size_t n){if(tracking)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void*operator new[](std::size_t n){return::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
namespace {using T=ks::StateProgramLoadService;struct Resource{std::vector<uint8_t>m=std::vector<uint8_t>(1<<24);int previous=-1;unsigned cost=0,last=0,events=0;uint64_t reads=0,writes=0;void byte(uint32_t a,uint8_t v){m[a&0xffffff]=v;}void word(uint32_t a,uint16_t v){byte(a,v>>8);byte(a+1,v);}void wide(uint32_t a,uint32_t v){word(a,v>>16);word(a+2,v);}void observe(uint32_t a,unsigned dt){check(a<m.size()&&(a<0xfff000||a>=0xfffc00)&&dt&&dt<=cost&&dt>=last,"Native program resource/time/CPU-frame");last=dt;++events;}uint8_t read(uint32_t a,unsigned dt){observe(a,dt);++reads;return a==0x400004||a==0x600004?255:m[a];}void write(uint32_t a,uint8_t v,unsigned dt){observe(a,dt);++writes;m[a]=v;previous=a<0x400000||(a>=0xfffd10&&a<0xffffa0)?int(a):-1;}void phase(unsigned c){cost=c;last=events=0;}};
struct Resolver{bool operator()(uint8_t c,uint32_t raw)const{return c==raw&&(c==0||c==2||c==3||c==4||c==6);}};
void seed(Resource&r,unsigned n,bool active){std::fill(r.m.begin(),r.m.end(),0);r.previous=-1;r.wide(0x167bc,n&8?0x80030001u:0x169fc);r.wide(0x167c0,n&8?0x42034001u:0x16f12);r.byte(0x167ac,uint8_t(n%8+1));r.byte(0x167ad,uint8_t(n%100));r.byte(0x167aa,1);r.byte(0x167ab,uint8_t(n%4));r.byte(0x167ba,uint8_t(n&1));r.byte(0x167bb,255);r.byte(0x16798,uint8_t(n%4));r.byte(0x169ed,n&16?63:127);r.byte(0x167a2,uint8_t(n&2));r.byte(0x174a6,uint8_t(n==63?0:active?8:1));r.byte(0x167d0,15);r.byte(0x167d1,15);r.word(0x159f2,0xffff);r.word(0xffed6c,45);r.word(0xffed6e,17);r.byte(0xffff8a,0xf0);r.byte(0xffff62,255);r.byte(0xfffeb1,255);r.byte(0x158f2,uint8_t(n));
for(const auto&s:ks::StateReloadPanelService::schema)for(unsigned i=0;i<8;++i)r.byte(0xfd66+8*s.key+i,s.bytes[i]);for(unsigned c:{0u,2u,3u,4u,6u})r.wide(0x1013e + 4*c,c);for(unsigned t=0;t<48;++t){r.byte(0x1c0+5*t,t%4);r.byte(0x1c1+5*t,1);r.byte(0x1c2+5*t,255);r.byte(0x1c3+5*t,7);r.byte(0x1c4+5*t,t%4);}for(unsigned bank=0;bank<4;++bank){const auto base=0x845800+1024*bank;for(unsigned part=0;part<4;++part){for(unsigned i=0;i<256;++i)r.byte(base+256*part+i,uint8_t(n*7+i*3));r.byte(base+256*part+187,1);r.byte(base+256*part+188,0);}r.byte(base+189,15);r.byte(base+190,15);}if(active)for(unsigned i=0;i<8;++i){const auto at=0x17560+20*i;r.wide(at,0x80300000u+256*i);r.byte(at+4,uint8_t(i%4));r.word(at+8,uint16_t(0x7fff-i));}}
}
int main(){try{auto resource=std::make_unique<Resource>();auto storage=std::make_unique<std::aligned_storage_t<sizeof(T),alignof(T)>>();std::vector<uint8_t>snapshot(sizeof(T));uint64_t graphs=0,phases=0,rejects=0,full=0,guards=0;uint32_t components=0;Resolver resolver;
for(unsigned kind=0;kind<3;++kind)for(unsigned n=0;n<64;++n){auto&r=*resource;seed(r,n,n&4);const bool wait=kind<2&&(n&32);if(wait){r.word(0xffed6c,255);r.word(0xffed6e,0);}tracking=true;auto*t=new(storage.get())T(T::Kind(kind),T::Input{0x010b});tracking=false;unsigned steps=0,waits=0;bool released=false;while(!t->complete()){if(wait&&!released)if(const auto*s=t->serial())if(s->atTransmit(ks::SerialTransmitTask::Stage::ReadConsumer)){if(++waits==4){r.word(0xffed6e,128);released=true;++full;}}const auto prev=r.previous;const auto cost=t->nextClocks(prev);check(cost,"Program deadlock");r.phase(cost);std::memcpy(snapshot.data(),t,sizeof(T));tracking=true;const auto no=t->advanceBefore(cost-1,[&](uint32_t a,unsigned dt){return r.read(a,dt);},[&](uint32_t a,uint8_t v,unsigned dt){r.write(a,v,dt);},resolver,prev);tracking=false;check(!no&&!r.events&&!std::memcmp(snapshot.data(),t,sizeof(T)),"Rejected budget changed program graph");++rejects;tracking=true;const auto used=t->advanceBefore(cost,[&](uint32_t a,unsigned dt){return r.read(a,dt);},[&](uint32_t a,uint8_t v,unsigned dt){r.write(a,v,dt);},resolver,prev);tracking=false;check(used==cost,"Program clocks");if(t->effect().write)r.previous=-1;check(++steps<1000000,"Program bound");++phases;}if(wait)check(released,"Full UART release path missing");if(kind==2)check(!r.m[0x16783]&&t->summary().loaded&&t->voices()->complete(),"Complete load oracle");components|=t->components();tracking=true;t->~T();tracking=false;++graphs;}
for(uint32_t bad:{0u,0xffefffu,0xfff000u,0xfff700u,0x42fff000u,0xffff51u}){auto&r=*resource;seed(r,0,false);r.wide(0x167bc,bad);check(!T::admitted(T::Kind::LoadSingle,[&](uint32_t a){return r.m[a];},resolver),"Invalid program target admitted");++guards;}
for(unsigned landing=0;landing<6;++landing)for(uint32_t bad:{0xffefffu,0xfff700u,0x42fff000u,0x80000500u}){auto&r=*resource;seed(r,0,false);r.byte(0x167ac,5);T graph(T::Kind::LoadSingle);unsigned steps=0;while(true){bool at=false;if(const auto*d=graph.data()){if(landing<3){if(const auto*t=d->task<ks::StateSingleLoadTask>()){using S=ks::StateSingleLoadTask::Stage;at=t->stage()==(landing==0?S::ReadTarget:landing==1?S::ReadOverlayTarget:S::ReadLateTarget);}}else if(landing==3){if(const auto*t=d->task<ks::StateGlobalsTask>())at=t->stage()==ks::StateGlobalsTask::Stage::ReadLiveBase;}else if(const auto*t=d->task<ks::StateParameterExpandTask>())at=t->stage()==(landing==4?ks::StateParameterExpandTask::Stage::ReadCurrentBase:ks::StateParameterExpandTask::Stage::ReadLiveBase);}if(at)break;const auto cost=graph.nextClocks(r.previous);r.phase(cost);graph.advanceBefore(cost,[&](uint32_t a,unsigned dt){return r.read(a,dt);},[&](uint32_t a,uint8_t v,unsigned dt){r.write(a,v,dt);},resolver,r.previous);if(graph.effect().write)r.previous=-1;check(++steps<20000,"Pure actual guard landing");}const auto pointer=landing==3||landing==5?0x167c0u:0x167bcu;r.wide(pointer,bad);r.phase(graph.nextClocks(r.previous));const auto writes=r.writes;bool threw=false;try{graph.advanceBefore(r.cost,[&](uint32_t a,unsigned dt){return r.read(a,dt);},[&](uint32_t a,uint8_t v,unsigned dt){r.write(a,v,dt);},resolver,r.previous);}catch(const std::logic_error&){threw=true;}check(threw&&r.events==4&&r.writes==writes,"Pure live pointer guard reached invalid derived resource");++guards;}
check(!allocations,"Native program allocated");std::cout<<"PASS program pure graphs="<<graphs<<" phases="<<phases<<" wholeobject_rejects="<<rejects<<" reads="<<resource->reads<<" writes="<<resource->writes<<" fullUART="<<full<<" guards="<<guards<<" components="<<components<<" bytes="<<sizeof(T)<<" allocations="<<allocations<<'\n';return 0;}catch(const std::exception&e){tracking=false;std::cerr<<e.what()<<'\n';return 1;}}
